#!/bin/bash
# Task 184-w22-full -- meshsim sim/ WORKER22 (branch sim-w22 bb6ed970; P4, inventory C5, C7).
# v1.3's run_tests.sh full-only steps engine-full (EngineTest -1 full: the all-to-alls on four data sets at full size,
# the radix sort at 16,384 keys) and rdport-full (ReadPortGatherTest -1 full) on the C++ suites (tests/suite_engine.cpp,
# suite_rdport.cpp; clang, the suite build, as the Makefile builds them), their printed lines against v1.3's logs
# (tests/p4suites/engine-full.log, rdport-full.log, made by Quest 176) with tests/p4_lines.sh (P4_ALLOW_FAIL: the FAIL
# lines listed, the printed lines compared). Expected FAILs, not this task's: W26's invariants 3 and 6 (EngineTest),
# invariant 8 and the command-slot check F4 (ReadPortGatherTest). rdport-full: the groups ported (from C, gather with its
# 65,536-value row, gather from C), each its own block; the other groups wait on harness work. No Java. Not timing (each
# step's time recorded only to plan). From an embedded kit. Writes only results/184-w22-full/. Scratch in /tmp, removed
# first and at the end. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/184-w22-full; mkdir -p "$RES"
W=/tmp/w22-184; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "31ac6577088f8886e3225f8b6ac6a2377b154eb11410bddaa9e90293a217f24e" ] || { echo "kit sha256 mismatch (want 31ac6577088f8886e3225f8b6ac6a2377b154eb11410bddaa9e90293a217f24e)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KS=$W/kit/sim
FAIL=0
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
echo "kit: $(cat $W/kit/VERSION); host $(hostname); $(nproc) CPUs; $(clang++ --version | head -1); $(lscpu | grep 'Model name' | head -1)"
cd "$KS"
make MODE=suite -j8 build/clang-suite/suite_engine build/clang-suite/suite_rdport > "$RES/build.log" 2>&1 && verdict build PASS || { tail -20 "$RES/build.log"; verdict build FAIL; echo FAILED; exit 1; }
B=build/clang-suite
lines() {   # NAME FIXTURE CMD...: the printed lines of CMD against FIXTURE, its output and the time kept
  local name=$1 fix=$2; shift 2; local t0=$(date +%s)
  if P4_ALLOW_FAIL=1 bash tests/p4_lines.sh "$fix" "$@" > "$RES/$name.cmp" 2>&1; then verdict "$name" PASS; else verdict "$name" FAIL; fi
  echo "$name: $(( $(date +%s) - t0 )) s"; cat "$RES/$name.cmp"
}
( lines engine-full tests/p4suites/engine-full.log $B/suite_engine -1 full ) > "$W/e.out" 2>&1 & pe=$!
( lines rdport-full-fromc tests/p4suites/rdport-full.log $B/suite_rdport -1 full --only=fromc
  lines rdport-full-gather tests/p4suites/rdport-full.log $B/suite_rdport -1 full --only=gather
  lines rdport-full-gatherc tests/p4suites/rdport-full.log $B/suite_rdport -1 full --only=gatherc ) > "$W/r.out" 2>&1 & pr=$!
wait $pe; wait $pr
cat "$W/e.out" "$W/r.out"
echo; cat "$RES/VERDICTS"
grep -q FAIL "$RES/VERDICTS" && { echo FAILED; exit 1; } || { echo DONE; exit 0; }
